import { spawn } from 'node:child_process';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const variant = process.argv[2];
const port = 36113;
const args = ['--no-sandbox','--disable-setuid-sandbox','--disable-dev-shm-usage','--headless',
  `--user-data-dir=${mkdtempSync(join(tmpdir(),'ud-'))}`, `--crash-dumps-dir=${mkdtempSync(join(tmpdir(),'cd-'))}`,
  '--enable-logging','--v=1','--no-crashpad','--disable-background-networking','--disable-component-update',
  '--disable-domain-reliability','--no-pings','--disable-crash-reporter',`--remote-debugging-port=${port}`];
if (variant === 'url') args.push('about:blank');
const child = spawn('/usr/bin/google-chrome-stable', args, { stdio: 'ignore', detached: variant !== 'attached' });
const start = performance.now();
let exited = null; child.on('exit', (c) => { exited = c; });
for (let i = 0; i < 120; i++) {
  try { const r = await fetch(`http://127.0.0.1:${port}/json/version`); if (r.ok) { console.log(`variant=${variant} PORT READY after ${((performance.now()-start)/1000).toFixed(2)} s`); break; } } catch {}
  if (exited !== null) { console.log(`variant=${variant} CHROME EXITED code=${exited} after ${((performance.now()-start)/1000).toFixed(2)} s`); break; }
  await new Promise((r) => setTimeout(r, 250));
  if (i === 119) console.log(`variant=${variant} NOT READY after 30 s`);
}
try { process.kill(-child.pid, 'SIGTERM'); } catch { try { child.kill(); } catch {} }
EOF
