import subprocess, re
A = subprocess.run(["git","show","refactor/slot-coordinator-owns-sync-managers:tests/test_binary_sensor.py"],capture_output=True,text=True,check=True).stdout
B = subprocess.run(["git","show","HEAD:tests/test_binary_sensor.py"],capture_output=True,text=True,check=True).stdout
def funcs(src):
    parts = re.split(r"(?=\n\nasync def |\n\ndef )", src)
    out={}
    for p in parts[1:]:
        m=re.match(r"\n\n(?:async )?def (\w+)\(", p)
        if m: out[m.group(1)]=p
    return out
fa, fb = funcs(A), funcs(B)
pin_names=[n for n in fb if "pin_in_sync" in n]
assert pin_names, "no pin tests in B"
add="".join(fb[n] for n in pin_names if n not in fa)
s=A.rstrip("\n")+"\n"+add
s=s.replace('''    entity_obj = get_in_sync_entity_obj(hass, entity_id)
    assert entity_obj._managers == []
    assert entity_obj.extra_state_attributes == {}
''','''    entity_obj = get_in_sync_entity_obj(hass, entity_id)
    assert entity_obj.is_on is None
    assert entity_obj.extra_state_attributes == {}
''')
# imports B had for the pin tests
hb=B.split("\nasync def ")[0]; ha=A.split("\nasync def ")[0]
for name in ("ATTR_PIN_IN_SYNC","pin_in_sync_entity_id","LockOperationFailed","STATE_UNAVAILABLE"):
    if name in add and re.search(rf"\b{name}\b", ha) is None:
        if name=="ATTR_PIN_IN_SYNC": s=s.replace("    ATTR_IN_SYNC,\n","    ATTR_IN_SYNC,\n    ATTR_PIN_IN_SYNC,\n",1)
        elif name=="pin_in_sync_entity_id": s=s.replace("from .common import (\n","from .common import (\n    pin_in_sync_entity_id,\n",1)
        elif name=="STATE_UNAVAILABLE": s=s.replace("    STATE_ON,\n","    STATE_ON,\n    STATE_UNAVAILABLE,\n",1)
        elif name=="LockOperationFailed": s=s.replace("    LockOperationFailed,\n","    LockOperationFailed,\n",1)
open("tests/test_binary_sensor.py","w").write(s)
print("pin tests:", pin_names)
EOF
